import { U } from './registry.mjs';
const c = 'dev';
const D = (id, names, shorts, x) => U(id, c, names, shorts, { icon: 'code', ...x });
export default [
  D('file-hash-generator', ['File Checksum Generator (SHA-256, MD5, SHA-1)', 'Datei-Prüfsumme berechnen (SHA-256, MD5, SHA-1)', 'Generator sum kontrolnych plików (SHA-256, MD5, SHA-1)', 'Generátor kontrolních součtů souborů (SHA-256, MD5, SHA-1)'],
    ['Calculate and compare file hashes in your browser to verify downloads.', 'Datei-Hashes im Browser berechnen und vergleichen, um Downloads zu prüfen.', 'Oblicz i porównaj hashe plików w przeglądarce, aby zweryfikować pobrania.', 'Spočítejte a porovnejte hashe souborů v prohlížeči a ověřte stažené soubory.'],
    { title: 'File Hash Generator – SHA-256, SHA-1, MD5 & SHA-512 Checksum of Any File', about: ['Download pages publish a checksum so you can check that the file is exactly what the publisher built. Drop the file here, paste the published value and you immediately see whether they match. SHA-256, SHA-384, SHA-512, SHA-1 and MD5 can be calculated at once, for files or for typed text.', 'SHA-1, SHA-256, SHA-384 and SHA-512 use the browser\'s Web Crypto API (native code). MD5 is not part of Web Crypto, so it is implemented here as an incremental algorithm that reads the file in 8 MB pieces and updates the hash piece by piece, showing progress. Results are verified against the published test vectors of each algorithm. MD5 and SHA-1 are broken for security purposes (collisions can be created), so use SHA-256 to verify downloads against tampering; MD5 remains fine for spotting accidental corruption.'],
      steps: ['Drop a file (or type text) and choose the algorithms.', 'Optionally paste the checksum from the download page into the compare field.', 'Read the green or red result and copy the hash you need.'], faqs: [['Is my file uploaded?', 'No. The file is read and hashed on your device. The page makes no network request with your data.'], ['Which hash should I use?', 'SHA-256 to verify downloads. MD5 and SHA-1 only to detect accidental changes, because they are not collision-resistant.']],
      related: ['base64-encoder', 'uuid-generator', 'password-generator', 'text-base-converter'], links: ['files:inspector'], test: ['abc', 'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad'] }),
  D('subnet-calculator', ['Subnet Calculator (CIDR, Netmask, IP Range)', 'Subnetz-Rechner (CIDR, Netzmaske, IP-Bereich)', 'Kalkulator podsieci (CIDR, maska, zakres IP)', 'Kalkulačka podsítí (CIDR, maska, rozsah IP)'],
    ['Network, broadcast, usable hosts and subnet splitting for any IPv4 range.', 'Netzwerk, Broadcast, nutzbare Hosts und Subnetz-Aufteilung für jeden IPv4-Bereich.', 'Sieć, broadcast, użyteczne hosty i podział na podsieci dla dowolnego zakresu IPv4.', 'Síť, broadcast, použitelné hostitele a dělení na podsítě pro libovolný rozsah IPv4.'],
    { title: 'Subnet Calculator – CIDR to Netmask, Host Range & Subnet Splitter (IPv4)', about: ['Enter 192.168.1.10/24 or an address with a mask such as 10.1.2.3 255.255.0.0 and see the network and broadcast address, the first and last usable host, the number of hosts, the wildcard mask, the binary mask, the address class and whether the range is private, loopback or public. Optionally split the network into equal smaller subnets.', 'The prefix length n gives a mask of n one-bits; the network address is the IP AND the mask, the broadcast address is the network OR the inverted mask, and the usable hosts are 2^(32−n) − 2 (the network and broadcast addresses are reserved). /31 networks (point-to-point links, RFC 3021) have two usable addresses and /32 is a single host. Masks must be contiguous, which is validated. Splitting a /24 into /26 gives 4 subnets of 64 addresses each.'],
      steps: ['Enter an address with a prefix (/24) or a subnet mask.', 'Read the network details.', 'Optionally enter a longer prefix to split the network.'], faqs: [['How many hosts does a /24 have?', '254 usable hosts (256 addresses minus the network and broadcast address).'], ['What is a wildcard mask?', 'The inverse of the subnet mask; used in router access lists (for /24 it is 0.0.0.255).']],
      related: ['cron-expression-translator', 'http-status-codes', 'number-base-converter', 'curl-converter'], links: ['culators:subnet'], test: ['', '192.168.1.0/24'] }),
  D('cron-expression-translator', ['Cron Expression Translator', 'Cron-Ausdruck verständlich übersetzen', 'Tłumacz wyrażeń cron', 'Překladač výrazů cron'],
    ['Translate cron schedules into plain English and see the next run times.', 'Cron-Zeitpläne in verständliche Sprache übersetzen und die nächsten Ausführungen sehen.', 'Przetłumacz harmonogramy cron na zrozumiały język i zobacz najbliższe uruchomienia.', 'Přeložte plány cron do srozumitelného jazyka a zobrazte příští spuštění.'],
    { title: 'Cron Expression Translator – Explain Cron Schedules & Preview Next Runs', about: ['What does "30 4 1,15 * 5" do? Paste a crontab schedule and read it in plain English, then check the next dates it will run. Presets cover common schedules such as every 5 minutes, weekdays at 9:00 or the first of every month.', 'The five fields (minute, hour, day of month, month, day of week) are parsed with support for lists (1,15), ranges (1-5), steps (*/10, 1-30/5), month and weekday names and the @daily-style aliases. Invalid values are reported with the reason. Next runs are found by stepping forward minute by minute and testing each field. Like real cron, when both the day-of-month and the day-of-week field are restricted, a job runs when either matches, a frequent source of surprises that the description points out. Times are shown in UTC or your local time, so you can check them against your server\'s time zone.'],
      steps: ['Type or pick a cron expression.', 'Read the plain-English description.', 'Check the list of upcoming runs, in UTC or local time.'], faqs: [['What do the five fields mean?', 'Minute (0–59), hour (0–23), day of month (1–31), month (1–12) and day of week (0–6, Sunday = 0).'], ['Why does "0 0 13 * 5" run on the 13th AND on Fridays?', 'When both day fields are restricted, standard cron runs the job if either one matches.']],
      related: ['unix-timestamp-converter', 'recurring-dates-generator', 'subnet-calculator', 'regex-explainer'], links: [], test: ['', 'On weekdays'.replace('On', 'on')] }),
  D('http-status-codes', ['HTTP Status Codes Reference', 'HTTP-Statuscodes Referenz', 'Kody statusu HTTP – ściągawka', 'Přehled stavových kódů HTTP'],
    ['Search every HTTP status code with a plain explanation and a fix.', 'Jeden HTTP-Statuscode suchen, mit verständlicher Erklärung und Lösung.', 'Wyszukaj każdy kod statusu HTTP z prostym wyjaśnieniem i poradą.', 'Vyhledejte každý stavový kód HTTP s jednoduchým vysvětlením a řešením.'],
    { title: 'HTTP Status Codes List – 200, 301, 404, 500 Explained with Troubleshooting', about: ['Search by number or keyword to see what a status code means and what to do about it. All codes from 1xx to 5xx in the IANA registry that matter in practice are listed, grouped by class, each with a short explanation and a hint for fixing it.', 'The first digit gives the class: 1xx informational, 2xx success, 3xx redirection, 4xx client error and 5xx server error. For each code the entry explains what the server is saying and the most common cause and fix: for example 502 means a proxy got an invalid answer from the application behind it, 504 means the application was too slow, and 429 means you are rate-limited and should wait for Retry-After. The search covers codes, names and descriptions.'],
      steps: ['Type a code (404) or a keyword (redirect, timeout).', 'Optionally filter by class.', 'Read the explanation and what to try.'], faqs: [['What is the difference between 401 and 403?', '401 means you are not authenticated (no or invalid credentials). 403 means the server knows who you are but you are not allowed.'], ['301 or 302 for redirects?', '301 for permanent moves (search engines transfer ranking), 302 or 307 for temporary ones.']],
      related: ['curl-converter', 'user-agent-decoder', 'robots-txt-generator', 'sitemap-xml-validator'], links: [], test: ['', 'Not Found'] }),
  D('curl-converter', ['cURL to JavaScript & Python Converter', 'cURL in JavaScript & Python umwandeln', 'Konwerter cURL na JavaScript i Python', 'Převodník cURL na JavaScript a Python'],
    ['Turn a curl command into working fetch and Python requests code.', 'Einen curl-Befehl in lauffähigen fetch- und Python-requests-Code umwandeln.', 'Zamień polecenie curl na działający kod fetch i Python requests.', 'Převeďte příkaz curl na funkční kód fetch a Python requests.'],
    { title: 'cURL to Fetch & Python Requests Converter – "Copy as cURL" to Code', about: ['API docs and browser dev tools give you curl commands. Paste one and get equivalent JavaScript fetch code and Python requests code with the same method, headers, body, basic auth and form fields.', 'The command is split into words following shell quoting rules (single and double quotes, backslash line continuations, $\'…\' strings), and the options are interpreted: -X, -H, -d / --data-raw / --data-binary, --json, -u, -F, -A, -e, -b, -k, -L and more, with options that do not change the request (-s, -v, -o, --compressed) ignored. JSON bodies are recognised and generated as JSON.stringify(...) or a Python dict (true/false/null become True/False/None); basic auth becomes an Authorization header or the auth= argument. Check generated code before running it: secrets in the command end up in your code.'],
      steps: ['Paste a curl command (in the browser: Network tab → right-click a request → Copy as cURL).', 'Read the generated JavaScript and Python.', 'Copy the code you need.'], faqs: [['Which curl options are supported?', 'Method, headers, data, JSON, auth, forms, user agent, referer, cookies, redirects and insecure mode. Unsupported options that affect the output are reported where possible.'], ['Is my command sent anywhere?', 'No. The conversion runs in your browser, which matters because curl commands often contain tokens.']],
      related: ['http-status-codes', 'base64-encoder', 'query-string-builder', 'basic-auth-header-generator'], links: [], test: ["curl -X POST https://api.example.com/x -H 'Content-Type: application/json' -d '{\"a\":1}'", 'await fetch("https://api.example.com/x"'] }),
  D('user-agent-decoder', ['User-Agent String Decoder', 'User-Agent-String entschlüsseln', 'Dekoder ciągu User-Agent', 'Dekodér řetězce User-Agent'],
    ['Find out browser, OS, device and engine from a user-agent string.', 'Browser, Betriebssystem, Gerät und Engine aus einem User-Agent-String ermitteln.', 'Sprawdź przeglądarkę, system, urządzenie i silnik z ciągu user-agent.', 'Zjistěte prohlížeč, systém, zařízení a engine z řetězce user-agent.'],
    { title: 'User Agent Parser – Decode Browser, OS & Device from UA String', about: ['Paste a user-agent string from a log file or support ticket and see the browser and version, operating system, device type, rendering engine and whether it is a bot. Your own user agent is prefilled.', 'The parser applies ordered rules, because user agents imitate each other: every Chrome-based browser says "Mozilla" and "Safari", Edge adds "Edg/", Opera "OPR/" and iPhone Chrome says "CriOS". It therefore checks the most specific tokens first, then reads the OS (Windows NT 10.0 is reported as "10 / 11" because both use it), device class (mobile, tablet, TV, bot) and the Android model. Bots are recognised by common crawler tokens. User-agent strings can be faked and Chrome is gradually freezing their detail, so use them for diagnostics, not for security or feature decisions.'],
      steps: ['Paste a user-agent string (or use yours).', 'Read the decoded browser, system and device.', 'Treat bot results with care: strings can be faked.'], faqs: [['Why does every browser say Mozilla?', 'For historical compatibility: early websites served better pages to Mozilla, so every browser claimed to be one.'], ['Why does Windows 11 show as Windows 10?', 'Both report NT 10.0 in the user agent. Windows 11 can only be told apart with client hints.']],
      related: ['http-status-codes', 'robots-txt-generator', 'email-header-analyzer', 'html-entity-encoder'], links: ['test:screen'], test: ['Mozilla/5.0 (iPhone; CPU iPhone OS 17_4_1 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.4.1 Mobile/15E148 Safari/604.1', 'Mobile phone'] }),
  D('html-entity-encoder', ['HTML Entity Encoder & Decoder', 'HTML-Entities kodieren & dekodieren', 'Enkoder i dekoder encji HTML', 'Kodér a dekodér HTML entit'],
    ['Convert special characters to HTML entities and back.', 'Sonderzeichen in HTML-Entities umwandeln und zurück.', 'Zamień znaki specjalne na encje HTML i z powrotem.', 'Převádějte speciální znaky na HTML entity a zpět.'],
    { title: 'HTML Entity Encoder & Decoder – & to &amp;, é to &eacute; and Back', about: ['Show "<b>" as text on a web page, escape user input or decode &amp;eacute; in scraped text. Choose whether to escape only the five characters that matter in HTML (& < > " \') or also every non-ASCII character, as named entities (&eacute;) or as decimal or hexadecimal numbers (&#233;, &#xE9;).', 'Encoding always escapes & first, so existing entities are not corrupted, and then < > " and \'. Named mode uses a table of about 120 common entities and falls back to numeric references for everything else (including emoji, which become one code point and not two surrogate halves). Decoding handles named, decimal and hex entities, rejects invalid code points (replaced by U+FFFD) and, like browsers, accepts a few legacy entities without semicolon. Escaping output is the main defence against cross-site scripting when text is inserted into HTML.'],
      steps: ['Choose encode or decode.', 'Pick how much to escape.', 'Paste your text and copy the result.'], faqs: [['Which characters must be escaped in HTML?', 'Always & and <. Inside attributes also the quote character used. > and the other quote are escaped for safety.'], ['What is the difference between &#233; and &eacute;?', 'Both display é. The numeric form works for every character; names exist only for a defined set.']],
      related: ['base64-encoder', 'text-base-converter', 'smart-quotes-to-ascii', 'query-string-builder'], links: [], test: ['<a href="x">&</a>', '&lt;a href=&quot;x&quot;&gt;&amp;&lt;/a&gt;'] }),
  D('base64-encoder', ['Base64 Encoder & Decoder (Text and Files)', 'Base64 kodieren & dekodieren (Text und Dateien)', 'Enkoder i dekoder Base64 (tekst i pliki)', 'Kodér a dekodér Base64 (text a soubory)'],
    ['Encode or decode Base64 and data URLs, for text and for files.', 'Base64 und Data-URLs kodieren oder dekodieren, für Text und Dateien.', 'Koduj i dekoduj Base64 i adresy data URL, dla tekstu i plików.', 'Kódujte a dekódujte Base64 a data URL, pro text i soubory.'],
    { title: 'Base64 Encode & Decode Online – Text, Files, URL-Safe & Data URLs', about: ['Convert text to Base64 or back, or encode any file by dropping it on the page. The tool detects whether your input looks like Base64 and decodes it automatically, recognises binary results such as images and PDFs and lets you download them, and supports the URL-safe alphabet used in JWTs and web links.', 'Text is encoded as UTF-8 bytes first, so accents and emoji work (unlike a plain btoa call, which fails on them). The standard alphabet uses + and / and = padding; the URL-safe variant replaces + and / with - and _ and often drops the padding. Decoding accepts both alphabets, whitespace, line breaks and data: prefixes, and reports invalid input clearly. Optional line wrapping at 64 or 76 characters follows MIME conventions. Base64 makes data about 33% larger and is not encryption.'],
      steps: ['Type text, paste Base64, or choose a file.', 'Pick URL-safe, padding and line-length options if needed.', 'Copy the result or download the decoded file.'], faqs: [['Is Base64 encryption?', 'No. It is a reversible encoding that anyone can decode. Never use it to protect secrets.'], ['Why does Base64 end with =?', 'Padding: the output length must be a multiple of 4 characters. The URL-safe form often omits it.']],
      related: ['basic-auth-header-generator', 'file-hash-generator', 'html-entity-encoder', 'text-base-converter'], links: ['open:png'], test: ['Hello, Wörld!', 'SGVsbG8sIFfDtnJsZCE='] }),
  D('color-converter', ['Color Converter (HEX, RGB, HSL, CMYK)', 'Farbumrechner (HEX, RGB, HSL, CMYK)', 'Konwerter kolorów (HEX, RGB, HSL, CMYK)', 'Převodník barev (HEX, RGB, HSL, CMYK)'],
    ['Convert colours between HEX, RGB, HSL, HSV and CMYK, with picker and eyedropper.', 'Farben zwischen HEX, RGB, HSL, HSV und CMYK umrechnen, mit Farbwähler und Pipette.', 'Konwertuj kolory między HEX, RGB, HSL, HSV i CMYK, z selektorem i pipetą.', 'Převádějte barvy mezi HEX, RGB, HSL, HSV a CMYK s výběrem a pipetou.'],
    { title: 'Color Converter – HEX to RGB, HSL, HSV & CMYK with Color Picker', about: ['Type a colour in any common notation (#2557D6, rgb(37 87 214), hsl(223 70% 48%), cmyk(83 59 0 16) or a name such as coral) and get all the others, ready to copy. Use the picker or, in Chrome and Edge, the eyedropper to sample a colour from anywhere on your screen.', 'RGB is the base. HSL and HSV are derived with the standard formulas, HEX is RGB in base 16 (with the alpha channel as an eighth and ninth digit when present), and CMYK uses the naive conversion K = 1 − max(R, G, B) with C, M and Y derived from it. That CMYK is a rough guide only: real print colours depend on ink, paper and colour profile. Alpha values from rgb(… / 50%) and 8-digit HEX are preserved.'],
      steps: ['Enter a colour or use the picker or eyedropper.', 'Read all formats.', 'Copy the one you need.'], faqs: [['How do I convert HEX to RGB?', 'Split the six digits into pairs and read each as a base-16 number: #2557D6 → 25, 57, D6 → 37, 87, 214.'], ['Can I convert RGB to CMYK exactly?', 'Not exactly: screens and printers have different colour ranges. The formula is a close estimate; use a colour-managed workflow for print jobs.']],
      related: ['hex-alpha-calculator', 'wcag-contrast-checker', 'css-box-shadow-generator', 'image-palette-extractor'], links: [], test: ['', 'rgb(37 87 214)'] }),
  D('uuid-generator', ['UUID / GUID Generator (v4 & v7)', 'UUID-/GUID-Generator (v4 & v7)', 'Generator UUID / GUID (v4 i v7)', 'Generátor UUID / GUID (v4 a v7)'],
    ['Generate batches of secure random UUIDs, including time-sortable v7.', 'Stapel sicherer zufälliger UUIDs erzeugen, auch zeitlich sortierbare v7.', 'Generuj partie bezpiecznych losowych UUID, także sortowalnych w czasie v7.', 'Generujte dávky bezpečných náhodných UUID včetně časově řaditelných v7.'],
    { title: 'UUID Generator – Bulk Random UUID v4 & Time-Ordered UUID v7', about: ['Create one UUID or ten thousand: version 4 (random) for general use, or version 7, which starts with a timestamp so IDs sort by creation time and keep database indexes fast. Output formats include upper case, without hyphens, Microsoft braces and SQL-quoted lists.', 'Version 4 sets 122 of its 128 bits from crypto.getRandomValues, the browser\'s cryptographically secure generator; the other 6 bits mark the version (4) and variant. Version 7 (RFC 9562) puts the Unix time in milliseconds into the first 48 bits and fills the rest with random bits. The chance of a v4 collision is negligible: you would need to generate about 2.7 quintillion UUIDs to reach a 50% chance of one duplicate.'],
      steps: ['Choose version, quantity and format.', 'Change a setting or press "Generate new batch".', 'Copy the list.'], faqs: [['What is the difference between UUID and GUID?', 'None in practice. GUID is Microsoft\'s name for the same 128-bit identifier.'], ['Should I use v4 or v7 as a database key?', 'v7 usually: it is random enough to be unique but increases over time, which avoids index fragmentation.']],
      related: ['password-generator', 'file-hash-generator', 'base64-encoder', 'number-base-converter'], links: ['culators:password'], test: ['', '-4'] }),
  D('number-base-converter', ['Number Base Converter (Binary, Octal, Decimal, Hex)', 'Zahlensystem-Umrechner (Binär, Oktal, Dezimal, Hex)', 'Konwerter systemów liczbowych (binarny, ósemkowy, dziesiętny, hex)', 'Převodník číselných soustav (binární, osmičková, desítková, hex)'],
    ['Convert integers between bases 2 to 36, with arbitrary size.', 'Ganze Zahlen zwischen den Basen 2 bis 36 umrechnen, in beliebiger Größe.', 'Konwertuj liczby całkowite między podstawami 2–36, o dowolnej wielkości.', 'Převádějte celá čísla mezi soustavami 2 až 36 libovolné velikosti.'],
    { title: 'Binary, Decimal, Hex & Octal Converter – Number Base Converter 2–36', about: ['Enter a number in any base from 2 to 36 and see it in binary, octal, decimal, hexadecimal and one more base of your choice. Prefixes such as 0x and 0b and underscores are understood, and numbers can be of any size, because the tool uses arbitrary-precision integers instead of floating point.', 'The input is read digit by digit in the chosen base into a BigInt, so values beyond 2^53 are exact (where JavaScript\'s normal numbers would lose digits), and then written in each target base with toString(base). Invalid digits are named in the error message. The bit count shows how many binary digits the number needs, which tells you whether it fits into 8, 16, 32 or 64 bits.'],
      steps: ['Enter the number and choose its base.', 'Read the other bases.', 'Copy the value you need.'], faqs: [['How do I convert hex to decimal?', 'Each hex digit is worth 16 times the one to its right: FF = 15×16 + 15 = 255.'], ['What is the largest number it can handle?', 'There is no fixed limit; memory is the only constraint.']],
      related: ['text-base-converter', 'subnet-calculator', 'color-converter', 'uuid-generator'], links: ['culators:conversion'], test: ['', 'Hexadecimal'] }),
  D('basic-auth-header-generator', ['Basic Auth Header Generator', 'Basic-Auth-Header erzeugen', 'Generator nagłówka Basic Auth', 'Generátor hlavičky Basic Auth'],
    ['Create the Authorization: Basic header from a username and password.', 'Den Authorization: Basic-Header aus Benutzername und Passwort erzeugen.', 'Utwórz nagłówek Authorization: Basic z nazwy użytkownika i hasła.', 'Vytvořte hlavičku Authorization: Basic z uživatelského jména a hesla.'],
    { title: 'Basic Authentication Header Generator – Authorization: Basic Base64', about: ['Enter a username and password and get the exact HTTP header, plus the equivalent curl option. Useful for testing APIs, configuring webhooks or setting up a reverse proxy.', 'HTTP Basic authentication (RFC 7617) joins username and password with a colon, encodes the result as Base64 (UTF-8) and sends it as "Authorization: Basic <value>". The example from the RFC, Aladdin / open sesame, gives QWxhZGRpbjpvcGVuIHNlc2FtZQ==. Base64 is not encryption, so credentials are readable by anyone who sees the request: only use Basic authentication over HTTPS. Your input stays in your browser.'],
      steps: ['Enter username and password.', 'Copy the header or the curl option.', 'Use it over HTTPS only.'], faqs: [['Is Basic authentication secure?', 'Only over HTTPS. The credentials are merely Base64-encoded, not encrypted.'], ['Can the username contain a colon?', 'No. The first colon separates user and password, so the username must not contain one.']],
      related: ['base64-encoder', 'curl-converter', 'password-generator', 'file-hash-generator'], links: [], test: ['', 'Authorization: Basic QWxhZGRpbjpvcGVuIHNlc2FtZQ=='] }),
  D('hex-alpha-calculator', ['Hex Color Alpha (Opacity to Hex) Calculator', 'Hex-Farbe mit Transparenz (Deckkraft in Hex)', 'Kalkulator przezroczystości hex (krycie na hex)', 'Kalkulačka průhlednosti hex (krytí na hex)'],
    ['Convert opacity percentages to two-digit hex alpha values like 50% = 80.', 'Deckkraft-Prozente in zweistellige Hex-Alphawerte umrechnen, z. B. 50 % = 80.', 'Zamień procenty krycia na dwucyfrowe wartości alfa hex, np. 50% = 80.', 'Převeďte procenta krytí na dvoumístné hex hodnoty alfa, např. 50 % = 80.'],
    { title: 'Hex Opacity Calculator – Alpha Percent to Hex Code (50% = 80)', about: ['Add transparency to a hex colour: enter the opacity in percent, get the two-digit suffix and, with a base colour, the complete 8-digit code (#2557D680). A table lists the usual steps from 0 to 100 percent.', 'The alpha channel runs from 0 to 255, so hex alpha = round(opacity ÷ 100 × 255), written in base 16: 50% → 127.5 → 128 → 80, 80% → 204 → CC. CSS and browsers use #RRGGBBAA (alpha last); Android resources use #AARRGGBB (alpha first), so check which one your platform expects.'],
      steps: ['Enter the opacity in percent.', 'Optionally enter the base colour.', 'Copy the suffix or the complete colour.'], faqs: [['What is 50% opacity in hex?', '80 (decimal 128), so #000000 at half opacity is #00000080.'], ['Does Android use the same order?', 'No: Android writes alpha first (#80000000).']],
      related: ['color-converter', 'wcag-contrast-checker', 'css-box-shadow-generator', 'number-base-converter'], links: [], test: ['', '80'] }),
  D('meta-viewport-generator', ['Meta Viewport Tag Generator', 'Meta-Viewport-Tag erzeugen', 'Generator znacznika meta viewport', 'Generátor značky meta viewport'],
    ['Build a correct viewport tag for responsive pages.', 'Einen korrekten Viewport-Tag für responsive Seiten erzeugen.', 'Zbuduj poprawny znacznik viewport dla stron responsywnych.', 'Vytvořte správnou značku viewport pro responzivní stránky.'],
    { title: 'Meta Viewport Tag Generator – Responsive Design & Mobile Settings', about: ['The viewport meta tag tells mobile browsers to use the device width instead of pretending to be a 980-pixel desktop. Choose the options and copy the tag; the generator keeps pinch-zoom enabled because disabling it fails accessibility requirements.', '"width=device-width, initial-scale=1" is the recommended default. viewport-fit=cover lets content extend under the notch on iPhones (combine it with safe-area insets in CSS), and a fixed width is only for special cases. maximum-scale and user-scalable=no are intentionally not offered: they block users with low vision from zooming (WCAG 1.4.4).'],
      steps: ['Choose the width and initial scale.', 'Add viewport-fit if you design for notched phones.', 'Copy the tag into your <head>.'], faqs: [['Do I need this tag?', 'Yes for every responsive website. Without it, phones show a scaled-down desktop layout.'], ['Should I disable zooming?', 'No. It harms accessibility and most browsers ignore it anyway.']],
      related: ['favicon-html-generator', 'opengraph-preview', 'css-box-shadow-generator', 'robots-txt-generator'], links: [], test: ['', '<meta name="viewport" content="width=device-width, initial-scale=1">'] }),
  D('favicon-html-generator', ['Favicon HTML Tag Generator', 'Favicon-HTML-Tags erzeugen', 'Generator znaczników HTML favicony', 'Generátor HTML značek favicony'],
    ['Generate the link tags and manifest for desktop and mobile icons.', 'Die Link-Tags und das Manifest für Desktop- und Mobil-Icons erzeugen.', 'Wygeneruj znaczniki link i manifest dla ikon na desktop i mobile.', 'Vygenerujte značky link a manifest pro ikony na počítači i mobilu.'],
    { title: 'Favicon HTML Generator – Link Tags for ICO, SVG, PNG & Apple Touch Icon', about: ['Choose which icon files you have and get the right <link> tags, in the order browsers prefer, plus a ready web app manifest. Pair it with the Favicon & App Icon Generator to create the image files themselves.', 'Modern setups need little: an SVG icon (scales, supports dark mode), a 32 px .ico or PNG fallback, a 180 px apple-touch-icon and a manifest with 192 and 512 px icons for Android and installable web apps. The tags and the manifest use the folder you enter, so paths work from every page.'],
      steps: ['Enter the folder that holds your icons.', 'Tick the icons you provide and set the theme colour.', 'Copy the tags into <head> and save the manifest.'], faqs: [['Which favicon sizes do I need?', 'An SVG or a 32×32 PNG/ICO for browsers, 180×180 for Apple devices and 192×192 and 512×512 for Android.'], ['Where do I put favicon.ico?', 'In your site\'s root folder; browsers ask for it there by default.']],
      related: ['favicon-generator', 'meta-viewport-generator', 'opengraph-preview', 'robots-txt-generator'], links: [], test: ['', '<link rel="icon" href="/favicon.svg" type="image/svg+xml">'] }),
  D('query-string-builder', ['URL Query String Builder', 'URL-Query-String erstellen', 'Kreator parametrów zapytania URL', 'Tvůrce parametrů URL (query string)'],
    ['Turn key-value pairs into a correctly percent-encoded URL query string.', 'Schlüssel-Wert-Paare in einen korrekt kodierten URL-Query-String umwandeln.', 'Zamień pary klucz-wartość na poprawnie zakodowany ciąg zapytania URL.', 'Převeďte páry klíč-hodnota na správně zakódovaný řetězec dotazu URL.'],
    { title: 'Query String Builder – URL Encode Parameters & Build API Request URLs', about: ['List parameters as key=value lines and get the encoded query string, optionally appended to a base URL. Spaces, ampersands, equals signs, accents and emoji are escaped correctly, and repeated keys can be written as tag=a&tag=b, tag[]=a&tag[]=b or tag=a,b.', 'Each key and value is encoded as UTF-8 with percent-escapes using encodeURIComponent plus the characters it leaves alone (! \' ( ) *), so the result is safe in any URL. Spaces become %20, or + if you choose the form-encoding style. Encoding the whole URL again would double-encode (%2520), so build the query string once and append it. Empty keys are skipped.'],
      steps: ['Enter parameters as key=value lines.', 'Choose how spaces and repeated keys are written.', 'Copy the query string or the full URL.'], faqs: [['%20 or + for spaces?', '%20 works everywhere in URLs. + only means space in form-encoded query strings (application/x-www-form-urlencoded).'], ['Why is & turned into %26?', 'Because a literal & inside a value would otherwise start a new parameter.']],
      related: ['url-extractor-tracking-remover', 'cache-buster-url-generator', 'curl-converter', 'html-entity-encoder'], links: [], test: ['', 'q=coffee%20%26%20tea'] }),
  D('cache-buster-url-generator', ['Cache Buster URL Generator', 'Cache-Buster-URL erzeugen', 'Generator adresów URL omijających cache', 'Generátor URL pro obejití cache'],
    ['Append a version or timestamp parameter so browsers fetch the latest file.', 'Einen Versions- oder Zeitstempel-Parameter anhängen, damit Browser die neueste Datei laden.', 'Dodaj parametr wersji lub znacznik czasu, aby przeglądarki pobrały najnowszy plik.', 'Připojte parametr verze nebo časové razítko, aby prohlížeče načetly nejnovější soubor.'],
    { title: 'Cache Busting URL Generator – Add ?v=timestamp to CSS & JS URLs', about: ['When you update a stylesheet or script and browsers or a CDN keep serving the old copy, a changed query string forces a fresh download. Paste the URLs, choose a timestamp, random string or fixed version and copy the busted URLs.', 'The parameter is set with the URL parser, so existing parameters stay and an existing ?v= is replaced, not duplicated. A timestamp changes on every click, which is ideal for testing; for production a version number or a content hash is better, because a constant URL can still be cached and a timestamp prevents caching altogether. File-name hashing (app.3f9a2c.js) is the most reliable method because some CDNs ignore query strings.'],
      steps: ['Paste the URLs, one per line.', 'Choose the parameter name and value type.', 'Copy the new URLs.'], faqs: [['Do all CDNs respect the query string?', 'Most do, but some are configured to ignore it. File names with a hash always work.'], ['How do I test without caching?', 'Use a timestamp while developing and open the developer tools with "Disable cache" ticked.']],
      related: ['query-string-builder', 'url-extractor-tracking-remover', 'http-status-codes', 'curl-converter'], links: [], test: ['', '?v='] }),
  D('ssl-certificate-expiry-checker', ['SSL Certificate Expiry Checker & Reminder', 'SSL-Zertifikat Ablauf prüfen & Erinnerung', 'Sprawdzanie wygaśnięcia certyfikatu SSL i przypomnienie', 'Kontrola vypršení certifikátu SSL a připomenutí'],
    ['Read a certificate, see how many days remain and download calendar reminders.', 'Ein Zertifikat lesen, die verbleibenden Tage sehen und Kalendererinnerungen herunterladen.', 'Odczytaj certyfikat, zobacz ile dni zostało i pobierz przypomnienia do kalendarza.', 'Přečtěte certifikát, zjistěte kolik dní zbývá a stáhněte si připomenutí do kalendáře.'],
    { title: 'SSL Certificate Expiration Calculator – Read PEM, Days Left & Calendar Reminders', about: ['Expired certificates take websites down. Paste a certificate (PEM) and the tool reads who it was issued to and by whom, the alternative names, the signature algorithm and the validity dates, and tells you how many days are left. A download adds reminders 30, 14 and 7 days before expiry to your calendar. If you only know the date, enter that instead.', 'The certificate is decoded in your browser with a small ASN.1/DER parser: it reads the TBSCertificate structure, the issuer and subject names, the notBefore and notAfter times (UTCTime or GeneralizedTime), the subjectAltName extension (DNS names and IP addresses) and the signature algorithm. The parser is checked against certificates generated with OpenSSL. Nothing is sent anywhere, and no live connection to your server is made: for that, run openssl s_client -connect host:443.'],
      steps: ['Paste the certificate, or enter the expiry date.', 'Read the days remaining and the details.', 'Download the reminders for your calendar.'], faqs: [['How do I get the certificate of my site?', 'In the browser, click the padlock → certificate → export, or run: openssl s_client -connect example.com:443 -showcerts.'], ['How long are certificates valid?', 'Public certificates are limited to 398 days today, and the maximum will become shorter in the coming years. Let\'s Encrypt issues 90-day certificates.']],
      related: ['file-hash-generator', 'email-header-analyzer', 'ics-event-generator', 'robots-txt-generator'], links: ['files:inspector'], test: ['', 'Paste a certificate'] }),
  D('email-header-analyzer', ['Email Header Analyzer', 'E-Mail-Header analysieren', 'Analizator nagłówków e-mail', 'Analyzátor hlaviček e-mailu'],
    ['Trace an email\'s route, delays and SPF, DKIM and DMARC results.', 'Den Weg einer E-Mail, Verzögerungen und SPF-, DKIM- und DMARC-Ergebnisse nachvollziehen.', 'Prześledź trasę wiadomości, opóźnienia oraz wyniki SPF, DKIM i DMARC.', 'Sledujte cestu e-mailu, zpoždění a výsledky SPF, DKIM a DMARC.'],
    { title: 'Email Header Analyzer – Trace Hops, Delays & SPF/DKIM/DMARC Results', about: ['Where did this mail come from, why did it take two hours and is the sender real? Paste the full headers and see the route as a table of hops with the time each server took, the SPF, DKIM and DMARC verdicts, and warnings when the From, Return-Path and Reply-To addresses do not match.', 'Headers are unfolded (continuation lines are joined) and every Received line is parsed for the sending host, receiving server, IP address, protocol and timestamp, then ordered from oldest to newest so delays between hops can be computed. The Authentication-Results header written by the receiving server provides the SPF, DKIM and DMARC results. Mismatches between the visible From domain and the envelope sender (Return-Path) or Reply-To are flagged, because phishing often relies on them; legitimate mailing services also trigger this, so judge in context. Headers never leave your browser.'],
      steps: ['Open the message source (Gmail: ⋮ → Show original) and copy the headers.', 'Paste them here.', 'Read the route, delays and authentication results.'], faqs: [['Which Received line is the first?', 'The last one in the list: each server adds its line on top. The tool reverses the order for you.'], ['What do SPF, DKIM and DMARC mean?', 'SPF checks the sending server, DKIM checks a cryptographic signature and DMARC requires that one of them matches the visible From domain.']],
      related: ['ssl-certificate-expiry-checker', 'user-agent-decoder', 'robots-txt-generator', 'http-status-codes'], links: ['files:mbox'], test: ['', 'Raw headers'] }),
  D('robots-txt-generator', ['robots.txt Generator & Validator', 'robots.txt Generator & Prüfer', 'Generator i walidator robots.txt', 'Generátor a validátor robots.txt'],
    ['Build a robots.txt or check an existing one for syntax mistakes.', 'Eine robots.txt erstellen oder eine vorhandene auf Syntaxfehler prüfen.', 'Utwórz plik robots.txt lub sprawdź istniejący pod kątem błędów składni.', 'Vytvořte robots.txt nebo zkontrolujte existující na chyby syntaxe.'],
    { title: 'robots.txt Generator & Validator – Allow, Disallow, Sitemap & Block AI Crawlers', about: ['Control which parts of your site crawlers may visit. Build a file from a list of blocked paths, exceptions and your sitemap URL, with an option to block AI-training crawlers, or paste an existing file and see every problem with its line number.', 'The validator checks each line against the robots.txt syntax (RFC 9309): field names, that rules belong to a User-agent group, that paths start with / or *, that Sitemap is an absolute URL and that crawl-delay is a number. It warns about directives search engines ignore (noindex, which Google no longer supports), and about "Disallow: /" for all agents, which blocks the whole site. robots.txt is a request, not access control: well-behaved crawlers follow it, but it does not hide pages, and blocked pages can still appear in search results if linked elsewhere.'],
      steps: ['Choose "Check" or "Build".', 'Paste your file, or enter the paths and sitemap URL.', 'Fix the listed problems, or copy and upload the new file to your site\'s root.'], faqs: [['Does Disallow remove a page from Google?', 'No. It only stops crawling. To keep a page out of search results use a noindex meta tag or password protection.'], ['Where must robots.txt be placed?', 'At the root of the host: https://example.com/robots.txt.']],
      related: ['sitemap-xml-validator', 'opengraph-preview', 'http-status-codes', 'user-agent-decoder'], links: [], test: ['', 'Groups'] }),
  D('sitemap-xml-validator', ['Sitemap XML Validator & Formatter', 'Sitemap-XML prüfen & formatieren', 'Walidator i formater sitemap XML', 'Validátor a formátovač sitemap XML'],
    ['Validate a sitemap against the standard and pretty-print it.', 'Eine Sitemap gegen den Standard prüfen und formatieren.', 'Zwaliduj sitemapę względem standardu i sformatuj ją.', 'Zvalidujte sitemapu podle standardu a naformátujte ji.'],
    { title: 'Sitemap XML Validator – Check sitemap.xml Syntax, URLs & Limits', about: ['Paste your sitemap and learn whether search engines will accept it: well-formed XML, correct namespace, absolute URLs, valid dates, priority and changefreq values, no duplicates and within the size limits. Each problem names the entry. The formatted XML can be copied or downloaded.', 'The file is parsed with the browser\'s XML parser (a malformed file is reported with the parser\'s message), the root must be urlset or sitemapindex in the sitemaps.org namespace, every url needs an absolute http(s) <loc> of at most 2,048 characters, lastmod must be in W3C datetime format, priority between 0 and 1 and changefreq one of the seven allowed values. A sitemap may hold at most 50,000 URLs and 50 MB uncompressed; larger sites need several files and an index. URLs from other hosts are flagged, because a sitemap may only list pages of its own site.'],
      steps: ['Paste your sitemap.xml.', 'Read the list of problems and the entry table.', 'Fix them, and copy the formatted XML.'], faqs: [['Do priority and changefreq matter?', 'Google ignores both. Accurate lastmod dates are what helps.'], ['How many URLs can a sitemap have?', '50,000 per file and 50 MB uncompressed. Use a sitemap index for more.']],
      related: ['robots-txt-generator', 'opengraph-preview', 'url-extractor-tracking-remover', 'http-status-codes'], links: ['open:formats'], test: ['', 'Type'.slice(0, 0) + 'sitemap.xml'] }),
  D('opengraph-preview', ['Open Graph & Social Share Preview', 'Open-Graph- & Social-Share-Vorschau', 'Podgląd Open Graph i udostępniania', 'Náhled Open Graph a sdílení'],
    ['Preview how a link looks on Facebook, X, LinkedIn and Slack and get the meta tags.', 'Vorschau, wie ein Link auf Facebook, X, LinkedIn und Slack aussieht, mit den Meta-Tags.', 'Zobacz podgląd linku na Facebooku, X, LinkedIn i Slacku i pobierz znaczniki meta.', 'Zobrazte náhled odkazu na Facebooku, X, LinkedInu a Slacku a získejte značky meta.'],
    { title: 'Open Graph Preview & Meta Tag Generator – Facebook, X, LinkedIn Share Cards', about: ['Fill in the title, description, URL and an image and see approximately how the shared link will look on Facebook, X (Twitter), LinkedIn and Slack or Discord. The page also writes the matching <title>, description, canonical, Open Graph and Twitter card tags, and warns when text will be cut off.', 'Open Graph (og:title, og:description, og:image, og:url) is read by most platforms when a link is pasted; X additionally uses twitter:card. Titles are best at 60 characters or less and descriptions at about 70–160 characters; images 1200 × 630 pixels (1.91:1). The preview image you choose here is only shown locally and never uploaded: the image URL for the tag must point to a file on your own site. Platforms cache previews, so use their debugger tools after publishing. The previews are approximations: each platform changes its layout from time to time.'],
      steps: ['Enter title, description, URL and site name.', 'Choose a preview image and enter the public image URL for the tag.', 'Copy the HTML into your page\'s <head>.'], faqs: [['What size should the Open Graph image be?', '1200 × 630 pixels, under about 5 MB, in JPG or PNG.'], ['Why does my old preview still show?', 'Platforms cache link previews. Use the Facebook Sharing Debugger or LinkedIn Post Inspector to refresh.']],
      related: ['meta-viewport-generator', 'favicon-html-generator', 'robots-txt-generator', 'sitemap-xml-validator'], links: [], test: ['', '<meta property="og:title"'] }),
  D('css-box-shadow-generator', ['CSS Box Shadow Generator', 'CSS-Box-Shadow-Generator', 'Generator cienia CSS box-shadow', 'Generátor CSS box-shadow'],
    ['Design layered box shadows visually and copy clean CSS.', 'Geschichtete Box-Shadows visuell gestalten und sauberes CSS kopieren.', 'Projektuj warstwowe cienie wizualnie i kopiuj czysty CSS.', 'Navrhujte vrstvené stíny vizuálně a kopírujte čisté CSS.'],
    { title: 'CSS Box Shadow Generator – Layered Shadows with Live Preview', about: ['Soft, realistic shadows are built from several layers. Add as many as you like, move the sliders for offset, blur, spread, colour and opacity, switch a layer to inset and watch the preview change. Copy the finished box-shadow declaration.', 'Each layer becomes "x y blur spread rgba(r, g, b, a)" with an optional inset keyword, and the layers are joined with commas; the first layer is painted on top. A common recipe for natural depth is a small, sharper shadow (y 2px, blur 6px, 10% opacity) combined with a large soft one (y 8px, blur 24px, negative spread). The output uses rgba() so opacity works in every browser.'],
      steps: ['Adjust the first layer, or add more layers.', 'Pick page and box colours to judge the result.', 'Copy the CSS.'], faqs: [['What does the spread value do?', 'It grows or shrinks the shadow. A negative spread with a large blur makes a soft shadow that does not spill to the sides.'], ['How many shadows can I stack?', 'As many as you like, though two or three layers are usually enough.']],
      related: ['color-converter', 'hex-alpha-calculator', 'meta-viewport-generator', 'wcag-contrast-checker'], links: [], test: ['', 'box-shadow:'] }),
  D('regex-explainer', ['Regular Expression Explainer & Tester', 'Regulären Ausdruck erklären & testen', 'Wyjaśnianie i testowanie wyrażeń regularnych', 'Vysvětlení a testování regulárních výrazů'],
    ['Break a regular expression into plain-language parts and test it live.', 'Einen regulären Ausdruck in verständliche Teile zerlegen und live testen.', 'Rozłóż wyrażenie regularne na zrozumiałe części i testuj na żywo.', 'Rozložte regulární výraz na srozumitelné části a testujte ho živě.'],
    { title: 'Regex Explainer – Visual Breakdown & Live Tester for Regular Expressions', about: ['Paste a regular expression and see it explained token by token in nested form: what each group, class, quantifier and anchor means. A test area highlights the matches line by line, so you can see whether it does what you think.', 'The expression is parsed by a small recursive reader that understands groups (capturing, non-capturing, named, lookahead and lookbehind), alternation, character classes, escapes such as \\d \\w \\s \\b, back-references and quantifiers (* + ? {n,m}, including lazy versions) and prints each part with its meaning, indented by nesting depth. Testing uses your browser\'s own JavaScript RegExp engine, so results match what your code will do. Syntax errors are reported with the engine\'s message.'],
      steps: ['Paste your regular expression and set flags.', 'Read the explanation of each part.', 'Edit the test text to check matches and non-matches.'], faqs: [['Which regex flavour is explained?', 'JavaScript (ECMAScript). Most syntax is shared with PCRE, Python and Java, but details such as lookbehind and named groups differ.'], ['What does the g flag do?', 'It finds all matches instead of stopping at the first one; the tester always shows all matches.']],
      related: ['regex-extractor', 'text-diff-checker', 'cron-expression-translator', 'filter-lines'], links: [], test: ['', 'What it means'] }),
  D('port-number-lookup', ['Port Number Lookup (Common TCP/UDP Ports)', 'Portnummern nachschlagen (TCP/UDP-Ports)', 'Wyszukiwarka numerów portów (TCP/UDP)', 'Vyhledávání čísel portů (TCP/UDP)'],
    ['Find which service uses a port, and which port a service uses.', 'Finde heraus, welcher Dienst einen Port nutzt und welchen Port ein Dienst verwendet.', 'Sprawdź, jaka usługa używa portu i jaki port ma dana usługa.', 'Zjistěte, jakou službu port používá a jaký port služba má.'],
    { title: 'Port Number Lookup – What Runs on Port 443, 3306, 22? (Common TCP/UDP Ports)', about: ['Type a port number or the name of a service and see the protocol (TCP or UDP), the usual service and a short note about it, including which ports should never be exposed to the internet, such as SMB (445), RDP (3389), databases or Docker\'s unencrypted API (2375).', 'The list contains about 70 ports that you meet in daily web, mail, database, VPN and development work. Port numbers are assigned by IANA: 0–1023 are well-known system ports, 1024–49151 are registered ports and 49152–65535 are dynamic or private ports. Having a default port does not mean a service must use it: anyone can run anything on any port, so a port number alone never proves what is behind it. The list is built into the page and works offline.'],
      steps: ['Type a port number or a service name.', 'Read the protocol and the note.', 'Check whether the port should be reachable from the internet.'], faqs: [['Which ports do websites use?', '80 for HTTP and 443 for HTTPS (and UDP 443 for HTTP/3).'], ['What is the difference between TCP and UDP ports?', 'TCP and UDP have separate port spaces. TCP is connection-oriented and reliable; UDP is faster and connectionless.']],
      related: ['subnet-calculator', 'http-status-codes', 'curl-converter', 'cron-expression-translator'], links: ['culators:subnet', 'test:wifi'], test: ['', 'HTTPS'] }),
  D('mime-type-lookup', ['MIME Type Lookup (File Extension to Content-Type)', 'MIME-Typ nachschlagen (Dateiendung zu Content-Type)', 'Wyszukiwarka typów MIME (rozszerzenie do Content-Type)', 'Vyhledávání typů MIME (přípona na Content-Type)'],
    ['Find the correct Content-Type for a file extension, or the extension for a MIME type.', 'Den richtigen Content-Type zu einer Dateiendung finden oder die Endung zu einem MIME-Typ.', 'Znajdź właściwy Content-Type dla rozszerzenia pliku lub rozszerzenie dla typu MIME.', 'Najděte správný Content-Type pro příponu souboru nebo příponu pro typ MIME.'],
    { title: 'MIME Type Lookup – Content-Type for .docx, .json, .svg, .webp and 70 More Extensions', about: ['Which Content-Type should a server send for a .docx, a .webp or a .wasm file? Search by extension, file name or by MIME type and get the registered value, including the long names of Office formats.', 'A MIME type (media type) has the form type/subtype, for example image/png, and tells browsers how to handle a response. Text types normally add a charset, e.g. text/html; charset=utf-8. If the type is wrong, browsers may download instead of displaying a file, refuse to run a script (module scripts need a JavaScript type) or reject a font. For unknown binary data the safe default is application/octet-stream. The list covers common web, document, image, audio, video, archive and font formats.'],
      steps: ['Type an extension such as .docx or a MIME type such as image/png.', 'Copy the matching Content-Type.', 'Configure your server or upload accordingly.'], faqs: [['What is the MIME type of a .docx file?', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document.'], ['What should I use if I do not know the type?', 'application/octet-stream, which tells the browser it is generic binary data.']],
      related: ['http-status-codes', 'base64-encoder', 'curl-converter', 'image-converter'], links: ['open:formats', 'files:inspector'], test: ['', 'application/pdf'] }),
  D('spf-dmarc-generator', ['SPF & DMARC Record Generator', 'SPF- & DMARC-Eintrag erstellen', 'Generator rekordów SPF i DMARC', 'Generátor záznamů SPF a DMARC'],
    ['Build the DNS TXT records that stop others from spoofing your domain\'s email.', 'Die DNS-TXT-Einträge erstellen, die E-Mail-Spoofing Ihrer Domain verhindern.', 'Zbuduj rekordy TXT DNS, które chronią e-maile Twojej domeny przed podszywaniem.', 'Vytvořte záznamy TXT v DNS, které chrání e-maily vaší domény před podvržením.'],
    { title: 'SPF & DMARC Generator – Create Email Authentication DNS Records (Free)', about: ['Choose which services may send email for your domain (Google, SendGrid, your own servers, IP ranges) and how strictly receivers should treat everything else, and get a ready SPF record. Then pick a DMARC policy, a reporting address and alignment and get the DMARC record. Both come with the exact host name to create them under and with warnings about common mistakes.', 'SPF lists the allowed senders in a TXT record on the domain (v=spf1 … ~all) and may cause at most 10 DNS lookups (each include, mx and a counts). DMARC (v=DMARC1; p=…) at _dmarc.your-domain tells receivers to quarantine or reject mail that fails SPF and DKIM alignment, and the rua address collects aggregate reports. A safe roll-out is p=none with reports, then quarantine (optionally with pct), then reject. The records are built locally and the tool checks syntax only: it does not look up your current DNS, and DKIM keys must come from your mail provider.'],
      steps: ['Enter your sending services and choose the SPF ending.', 'Pick the DMARC policy and a report address.', 'Create the two TXT records at your DNS provider.'], faqs: [['Can I have two SPF records?', 'No. A domain must have exactly one SPF record; merge all senders into it.'], ['Which DMARC policy should I start with?', 'p=none with a rua report address, then move to quarantine and reject when the reports show only legitimate senders.']],
      related: ['email-header-analyzer', 'subnet-calculator', 'robots-txt-generator', 'password-generator'], links: ['files:mbox'], test: ['', 'v=spf1'] }),
  D('css-flexbox-playground', ['CSS Flexbox Playground & Cheat Sheet', 'CSS-Flexbox-Spielwiese & Spickzettel', 'Plac zabaw i ściągawka CSS Flexbox', 'CSS Flexbox hřiště a tahák'],
    ['Click through flexbox settings, see the result live and copy the CSS.', 'Flexbox-Einstellungen anklicken, das Ergebnis live sehen und das CSS kopieren.', 'Przeklikaj ustawienia flexbox, zobacz wynik na żywo i skopiuj CSS.', 'Proklikejte nastavení flexboxu, uvidíte výsledek živě a zkopírujte CSS.'],
    { title: 'CSS Flexbox Playground – Visual justify-content, align-items & flex-wrap Cheat Sheet', about: ['Change flex-direction, justify-content, align-items, flex-wrap, align-content, gap and the number of items and watch the boxes rearrange immediately. The matching CSS is shown below and can be copied.', 'The main axis is the direction of the flex-direction (horizontal for row, vertical for column); justify-content distributes items along it, align-items positions them across it, and align-content only matters when wrapping creates more than one line. Items have varied heights so that the effect of align-items (stretch, center, baseline …) is visible. The playground uses the browser\'s real layout engine, so it always shows the true behaviour of your browser. It covers the container properties; item properties such as flex-grow, flex-shrink and flex-basis are described on MDN.'],
      steps: ['Change the container properties.', 'Watch the boxes move.', 'Copy the CSS.'], faqs: [['What is the difference between justify-content and align-items?', 'justify-content works along the main axis, align-items across it. Changing flex-direction swaps which is horizontal.'], ['Why does align-content do nothing?', 'It needs flex-wrap: wrap and enough items to create several lines.']],
      related: ['css-box-shadow-generator', 'color-converter', 'meta-viewport-generator', 'hex-alpha-calculator'], links: [], test: ['', 'display: flex'] }),
  D('webhook-signature-tester', ['Webhook Signature Tester (HMAC SHA-256)', 'Webhook-Signatur testen (HMAC SHA-256)', 'Tester podpisu webhooka (HMAC SHA-256)', 'Test podpisu webhooku (HMAC SHA-256)'],
    ['Calculate GitHub, Stripe and Slack style webhook signatures and check the one you received.', 'GitHub-, Stripe- und Slack-ähnliche Webhook-Signaturen berechnen und die empfangene prüfen.', 'Oblicz podpisy webhooków w stylu GitHub, Stripe i Slack i sprawdź otrzymany.', 'Vypočítejte podpisy webhooků ve stylu GitHub, Stripe a Slack a zkontrolujte přijatý.'],
    { title: 'Webhook Signature Tester – HMAC SHA-256 for GitHub, Stripe & Slack (Debug "Invalid Signature")', about: ['Paste the raw request body and the signing secret and see the signatures a sender would produce: GitHub\'s sha256= and legacy sha1=, Stripe\'s t=…,v1=…, Slack\'s v0=…, plain hex, Base64 (used by Shopify and others) and SHA-512. Paste the signature header you actually received and the tool tells you whether it matches one of them, which quickly shows if the problem is the secret, the body, the timestamp or the header format.', 'A webhook signature is an HMAC (keyed hash) of the exact bytes of the request body, sometimes prefixed by a timestamp: GitHub signs the body, Stripe signs "timestamp.body" and Slack "v0:timestamp:body". The calculation uses the Web Crypto API in your browser. The most common reason for "invalid signature" is that the body was parsed and re-serialised before verification: even a changed space or a missing final newline changes the HMAC, so always verify the raw body. Compare signatures with a constant-time function and check that the timestamp is recent to block replays. Use a test secret here; do not paste production secrets into any website.'],
      steps: ['Paste the raw body and the secret.', 'Optionally enter the timestamp and the received signature.', 'Compare the calculated signatures with the header you got.'], faqs: [['Why does my signature never match?', 'Usually the body was changed before hashing (parsed JSON, trimmed whitespace) or the wrong secret or header format is used.'], ['Is it safe to paste my secret?', 'Calculation is local, but use test secrets only. Treat any secret typed into a web page as exposed.']],
      related: ['file-hash-generator', 'jwt-decoder', 'base64-encoder', 'basic-auth-header-generator'], links: [], test: ['', 'GitHub'] }),
  D('font-converter', ['Font Converter (TTF/OTF to WOFF and back)', 'Schrift-Konverter (TTF/OTF in WOFF und zurück)', 'Konwerter czcionek (TTF/OTF na WOFF i z powrotem)', 'Převodník písem (TTF/OTF na WOFF a zpět)'],
    ['Convert a font file to WOFF for websites, or unpack WOFF to TTF/OTF.', 'Eine Schriftdatei für Websites in WOFF umwandeln oder WOFF zu TTF/OTF entpacken.', 'Konwertuj plik czcionki na WOFF dla stron lub rozpakuj WOFF do TTF/OTF.', 'Převeďte soubor písma na WOFF pro weby, nebo rozbalte WOFF na TTF/OTF.'],
    { icon: 'text', title: 'Font Converter – TTF and OTF to WOFF and WOFF to TTF Online (No Upload)', about: ['Drop a TTF or OTF font and get a WOFF file for your website, usually about a third smaller; drop a WOFF and get the TTF or OTF back. The tool shows the font family, style and number of glyphs, previews your own text in the font and writes the matching @font-face CSS for you to copy.', 'WOFF 1.0 is the same font data with every table compressed by zlib, so converting changes no outlines or metrics: the tables are copied byte for byte and only wrapped or unwrapped. That is why the conversion is exact and instant. WOFF2, the smallest web font format, needs Brotli compression and font-specific transforms, which this tool does not do; it tells you if you drop one. Font collections (.ttc) are also not supported. Check the font’s licence before you use it on a website: not every desktop font may be embedded.'],
      steps: ['Drop the font file.', 'Check the preview and the font details.', 'Download the converted file and copy the CSS.'], faqs: [['Why not WOFF2?', 'WOFF2 needs Brotli compression, which would require a large extra library. WOFF works in every current browser; for the last bit of size, use a build tool on your server.'], ['Does the conversion change how the font looks?', 'No. The glyph data is copied unchanged; only the packaging differs.']],
      related: ['favicon-html-generator', 'svg-optimizer', 'color-converter', 'zip-creator'], links: [], test: ['', 'Drop'] }),
  D('json-formatter', ['JSON Formatter and Validator', 'JSON formatieren und prüfen', 'Formatowanie i walidacja JSON', 'Formátování a kontrola JSON'],
    ['Format, minify, sort and validate JSON, with the exact error position.', 'JSON formatieren, minimieren, sortieren und prüfen, mit genauer Fehlerposition.', 'Formatuj, minimalizuj, sortuj i waliduj JSON, z dokładną pozycją błędu.', 'Formátujte, minimalizujte, řaďte a kontrolujte JSON s přesnou polohou chyby.'],
    { icon: 'code', title: 'JSON Formatter, Validator and Minifier Online (Free, No Upload)', about: ['Paste JSON and get it indented, minified or with sorted keys, or see exactly where it is invalid: the line, the column and what was expected, with the offending line and a pointer. An option accepts JSON with comments and trailing commas, as found in config files.', 'Validation uses a small parser of its own to explain errors, because browsers report them differently or without a position. The data is parsed and rewritten in your browser; numbers keep JavaScript’s precision, so integers above 9,007,199,254,740,991 can lose digits. The statistics show the type, the number of keys, the nesting depth and the size.'],
      steps: ['Paste the JSON or open a file.', 'Choose indentation, minify or sort keys.', 'Copy or download the result, or fix the error shown.'], faqs: [['Why does it say "Trailing comma"?', 'Strict JSON does not allow a comma after the last item. Remove it, or tick the option to allow comments and trailing commas.'], ['Are large numbers safe?', 'Numbers beyond 2^53 lose precision in JavaScript. Keep such values as strings if exact digits matter.']],
      related: ['data-format-converter', 'csv-to-json', 'json-to-csv', 'jwt-decoder'], links: [], test: ['{"b":1,"a":[1,2]}', '"a": ['] }),
  D('data-format-converter', ['JSON, YAML and XML Converter', 'JSON, YAML und XML umwandeln', 'Konwerter JSON, YAML i XML', 'Převodník JSON, YAML a XML'],
    ['Convert between JSON, YAML and XML in either direction.', 'Zwischen JSON, YAML und XML in beide Richtungen umwandeln.', 'Konwertuj między JSON, YAML i XML w obu kierunkach.', 'Převádějte mezi JSON, YAML a XML v obou směrech.'],
    { icon: 'code', title: 'JSON to YAML, YAML to JSON, XML to JSON Converter Online (No Upload)', about: ['Paste data in one format and get it in another: JSON to YAML for config files, YAML to JSON for APIs, XML to JSON and back. The input format is detected automatically, and the indentation can be chosen.', 'XML has attributes and text that JSON does not, so the usual convention is used: attributes become keys starting with "@", mixed text becomes "#text" and repeated elements become arrays; converting back reverses it. XML comments and processing instructions are dropped. YAML is read and written with js-yaml. Everything runs in your browser.'],
      steps: ['Paste the data or open a file.', 'Choose the target format (the input is detected automatically).', 'Copy or download the result.'], faqs: [['Why do XML attributes appear as "@name"?', 'JSON has no attributes. The "@" prefix marks them so that they can be turned back into attributes.'], ['Are YAML comments kept?', 'No. Comments are not part of the data and are dropped on conversion.']],
      related: ['json-formatter', 'csv-to-json', 'outline-converter', 'markdown-previewer'], links: [], test: ['a: 1', 'Detected input'] }),
  D('sql-formatter', ['SQL Formatter and Beautifier', 'SQL formatieren und verschönern', 'Formatowanie SQL (upiększanie)', 'Formátování SQL'],
    ['Make SQL queries readable with indentation and line breaks.', 'SQL-Abfragen mit Einrückung und Zeilenumbrüchen lesbar machen.', 'Spraw, by zapytania SQL były czytelne dzięki wcięciom i podziałom wierszy.', 'Zpřehledněte dotazy SQL odsazením a zalomením řádků.'],
    { icon: 'code', title: 'SQL Formatter – Beautify SQL for PostgreSQL, MySQL, SQL Server and More (No Upload)', about: ['Paste a long one-line query and get it formatted with each clause on its own line, indented joins and conditions and keywords in upper case. Choose the dialect (standard SQL, PostgreSQL, MySQL, MariaDB, SQLite, SQL Server, Oracle, BigQuery, Snowflake), the keyword case and the indentation.', 'The formatter is the open-source sql-formatter library, running in your browser; your queries are not sent anywhere, which matters when they contain table names or values from a real system. It formats; it does not check that the query would run, and unusual vendor syntax can be laid out differently than you would.'],
      steps: ['Paste the SQL.', 'Choose the dialect, keyword case and indentation.', 'Copy the formatted query.'], faqs: [['Does it validate my SQL?', 'No. It only formats. A syntax error may show up as a formatting error, but a valid-looking query can still fail on your database.'], ['Which dialect should I pick?', 'The one of your database. Standard SQL works for simple queries; vendor-specific features format best with the matching dialect.']],
      related: ['csv-to-sql', 'json-formatter', 'regex-tester', 'text-diff-checker'], links: [], test: ['select a,b from t where x=1', 'SELECT'] }),
  D('regex-tester', ['Regex Tester (JavaScript)', 'Regex-Tester (JavaScript)', 'Tester wyrażeń regularnych (JavaScript)', 'Tester regulárních výrazů (JavaScript)'],
    ['Test a regular expression live: matches, groups and replacement.', 'Einen regulären Ausdruck live testen: Treffer, Gruppen und Ersetzung.', 'Testuj wyrażenie regularne na żywo: dopasowania, grupy i zamianę.', 'Testujte regulární výraz naživo: shody, skupiny a nahrazení.'],
    { icon: 'code', title: 'Regex Tester – Test JavaScript Regular Expressions Online with Groups and Replace', about: ['Type a pattern and a text and see every match highlighted, with its position (line and column), numbered groups and named groups. Switch the flags (g, i, m, s, u) and try a replacement such as <$1> to see the result. Together with the Regex Explainer it helps you build and understand patterns.', 'The test uses the JavaScript regular-expression engine of your browser and runs in a background worker that is stopped after two seconds, so a pattern that backtracks catastrophically (for example (a+)+ on a long text) cannot freeze the page; you get a message instead. Other engines (PCRE, Python, .NET) differ in details such as lookbehind and named-group syntax.'],
      steps: ['Enter the pattern and choose the flags.', 'Paste or type the test text.', 'Read the highlighted matches and groups, and try a replacement.'], faqs: [['Why does it say the pattern took too long?', 'Nested repeats such as (a+)+ or (.*)* can take exponential time on some inputs. Make the pattern more specific.'], ['Will my pattern work in Python or PHP?', 'Often, but not always. Features like lookbehind, named groups and flags differ between engines; test in your target language.']],
      related: ['regex-explainer', 'regex-extractor', 'filter-lines', 'text-diff-checker'], links: [], test: ['', 'Matches'] }),
  D('markdown-previewer', ['Markdown Previewer (Live Preview)', 'Markdown-Vorschau (Live)', 'Podgląd Markdown (na żywo)', 'Náhled Markdownu (živě)'],
    ['See Markdown rendered as you type and copy the HTML.', 'Markdown beim Tippen als Vorschau sehen und das HTML kopieren.', 'Zobacz renderowany Markdown podczas pisania i skopiuj HTML.', 'Sledujte vykreslený Markdown při psaní a zkopírujte HTML.'],
    { icon: 'text', title: 'Markdown Previewer – Live Markdown Editor with HTML Output (No Upload)', about: ['Write or paste Markdown and see headings, lists, task lists, tables, quotes, code blocks, links and images rendered next to it. The copy button gives you the generated HTML. Open a .md file to check a README before you commit it.', 'The renderer supports the common CommonMark features plus GitHub-style tables, task lists and strikethrough. Raw HTML in the text is shown as text, not executed, and links with unsafe schemes such as javascript: are neutralised, so previewing untrusted Markdown is safe. Rare features (footnotes, definition lists, nested block quotes with lists) are not supported, and the look differs from GitHub’s.'],
      steps: ['Type, paste or open the Markdown.', 'Check the preview.', 'Copy the HTML or the Markdown.'], faqs: [['Is HTML inside Markdown rendered?', 'No. It is shown as text for safety. Use the generated HTML if you need a different result.'], ['Does it look exactly like GitHub?', 'The structure is the same for common features, but the styling is simpler.']],
      related: ['markdown-table-of-contents', 'markdown-to-email', 'markdown-to-docx', 'table-to-markdown'], links: [], test: ['# Hi', 'Words'] }),
  D('css-html-minifier', ['CSS, HTML and JSON Minifier', 'CSS, HTML und JSON minimieren', 'Minifikator CSS, HTML i JSON', 'Minifikace CSS, HTML a JSON'],
    ['Remove comments and whitespace to make CSS, HTML or JSON smaller.', 'Kommentare und Leerraum entfernen, um CSS, HTML oder JSON zu verkleinern.', 'Usuń komentarze i białe znaki, by zmniejszyć CSS, HTML lub JSON.', 'Odstraňte komentáře a mezery a zmenšete CSS, HTML nebo JSON.'],
    { icon: 'code', title: 'CSS, HTML and JSON Minifier Online – Reduce File Size (No Upload)', about: ['Paste CSS, HTML or JSON and get a compact version without comments and unnecessary whitespace, with the size before and after. CSS also loses redundant semicolons and zero units and gets short hex colours; HTML keeps the content of pre, textarea, script and style blocks intact.', 'This is a safe, conservative minifier: it removes only what does not change how the code works, and keeps strings, pre-formatted text and conditional comments. It does not rename anything or rewrite JavaScript; for that use a build tool. Always test the result, especially HTML with inline spacing between tags.'],
      steps: ['Paste the code.', 'Check the detected type (or choose it).', 'Copy the minified result and compare the sizes.'], faqs: [['Does it minify JavaScript?', 'No. Safe JavaScript minification needs a full parser; use a build tool such as esbuild or terser.'], ['Can minifying HTML break a page?', 'Rarely: whitespace between inline elements can matter. The tool keeps single spaces between inline content; test the page.']],
      related: ['json-formatter', 'svg-optimizer', 'image-compressor', 'text-diff-checker'], links: [], test: ['.a { margin: 0px; }', 'Saved'] }),
  D('lorem-ipsum-generator', ['Lorem Ipsum Generator', 'Lorem-Ipsum-Generator', 'Generator Lorem Ipsum', 'Generátor Lorem Ipsum'],
    ['Generate placeholder text by paragraphs, sentences or words.', 'Platzhaltertext nach Absätzen, Sätzen oder Wörtern erzeugen.', 'Generuj tekst zastępczy w akapitach, zdaniach lub słowach.', 'Generujte výplňový text po odstavcích, větách nebo slovech.'],
    { icon: 'text', title: 'Lorem Ipsum Generator – Placeholder Text for Designs and Mock-ups', about: ['Choose how many paragraphs, sentences or words you need, whether to start with the classic "Lorem ipsum dolor sit amet", and optionally wrap the paragraphs in <p> tags. Copy or download the text for a mock-up, a template or a layout test.', 'The words come from a Latin-looking list and are put together by a seeded random generator, so the same settings always produce the same text until you ask for a new one. The text has no meaning, which is the point: it lets you judge the look of a layout without being distracted by the content. For realistic data such as names and addresses use the Fake Data Generator.'],
      steps: ['Choose the amount and the unit.', 'Decide on the classic start and HTML tags.', 'Copy the text, or press "Generate new text" for a different one.'], faqs: [['Is Lorem Ipsum real Latin?', 'It is scrambled from a text by Cicero, so it looks like Latin but has no meaning.'], ['Can I get text in another language?', 'Not here. For names, addresses and numbers in German or English see the Fake Data Generator.']],
      related: ['dummy-data-generator', 'word-frequency-counter', 'text-splitter', 'character-counter'], links: [], test: ['', 'Words'] }),
  D('file-type-detector', ['File Type Detector (Identify Any File)', 'Dateityp erkennen (unbekannte Datei prüfen)', 'Wykrywanie typu pliku (rozpoznaj plik)', 'Rozpoznání typu souboru'],
    ['Find out what a file really is, from its content instead of its name.', 'Herausfinden, was eine Datei wirklich ist, anhand ihres Inhalts statt ihres Namens.', 'Sprawdź, czym naprawdę jest plik, po zawartości, a nie po nazwie.', 'Zjistěte, čím soubor skutečně je, podle obsahu, ne podle názvu.'],
    { icon: 'file', title: 'File Type Detector – Identify an Unknown File by Its Content (Magic Bytes, No Upload)', about: ['Drop a file with no extension, a strange extension or a name you do not trust and see what it really is: image, PDF, Office document, archive, audio, video, font, executable, database or text. For each file you get the detected type, the MIME type and whether the file name matches the content.', 'The type is read from the first bytes of the file (its "magic number"), the way the Unix file command does, so it does not depend on the name. ZIP-based formats are told apart by their entries (DOCX, XLSX, PPTX, EPUB, JAR, APK, OpenDocument), MP4-family files by their brand (MP4, MOV, HEIC, AVIF) and text files by their content (JSON, HTML, XML, SVG, scripts). About 60 common formats are recognised; a file that matches none is reported as unknown binary data. A mismatch between name and content is a warning sign for malware, but also happens innocently.'],
      steps: ['Drop one or more files.', 'Read the detected type and whether the name matches.', 'Rename the file with the right extension if needed.'], faqs: [['Is a mismatch dangerous?', 'It can be: malware often hides behind a harmless extension. It is also common after a wrong rename. Do not open files you do not trust.'], ['Is the file uploaded?', 'No. Only the first 70 KB are read in your browser.']],
      related: ['file-hash-generator', 'mime-type-lookup', 'exif-viewer', 'zip-extractor'], links: ['files:inspector'], test: ['', 'Drop'] }),
  D('folder-tree-generator', ['Folder Tree Generator (Directory Structure as Text)', 'Ordnerbaum erstellen (Verzeichnisstruktur als Text)', 'Generator drzewa folderów (struktura jako tekst)', 'Generátor stromu složek (struktura jako text)'],
    ['Turn a folder or a list of paths into a text tree for documentation.', 'Einen Ordner oder eine Pfadliste in einen Textbaum für die Dokumentation umwandeln.', 'Zamień folder lub listę ścieżek w drzewo tekstowe do dokumentacji.', 'Změňte složku nebo seznam cest na textový strom pro dokumentaci.'],
    { icon: 'code', title: 'Folder Tree Generator – Directory Structure as Text Tree for README (No Upload)', about: ['Choose or drop a folder, or paste a list of paths, and get the structure as a text tree with ├── and └── lines, ready for a README, a ticket or documentation. Options hide folders such as node_modules and .git, limit the depth, show only folders, show file sizes and sort by name or size.', 'Only the names and sizes of the files are read, never their content, and nothing leaves your computer. Pasted lists work with forward or back slashes, and paths ending in a slash are treated as folders. Empty folders appear when your browser reports them; for very large folders (tens of thousands of files) the browser may take a moment.'],
      steps: ['Drop or choose a folder, or paste paths.', 'Set the ignore list, depth and options.', 'Copy the tree or download it.'], faqs: [['Is the content of my files read?', 'No. Only names and sizes.'], ['How do I show only the top level?', 'Set "Maximum depth" to 1.']],
      related: ['outline-converter', 'markdown-table-of-contents', 'file-type-detector', 'zip-extractor'], links: [], test: ['src/app.js\nREADME.md', '├──'] }),
];
